import {readFileSync} from 'node:fs';
import {pairedStats,classifyRatio,median} from "/Users/ilyagulya/Projects/My/bend/evals/selfhost_corpus_calibration.ts";
const triads=JSON.parse(readFileSync(process.argv[2]!,'utf8'));
const protocol=JSON.parse(readFileSync(process.argv[3]!,'utf8')),limit=protocol.selected.costGate;
const result:any={schemaVersion:1,triads};
for(const [variant,baseline] of [['C','A'],['C','B'],['B','A']]){
 const comparison:any={};
 for(const metric of ['checkerCpuMs','checkerWallMs','footprintBytes','rssBytes']){
  const a=triads.map((t:any)=>t[baseline][metric]),c=triads.map((t:any)=>t[variant][metric]);
  const statistics=pairedStats(a,c);comparison[metric]={...statistics,direction:classifyRatio(statistics.ci95,.02)};
 }
 comparison.medianFootprintRatio=median(triads.map((t:any)=>t[variant].footprintBytes))!/median(triads.map((t:any)=>t[baseline].footprintBytes))!;
 result[variant+'_over_'+baseline]=comparison;
}
result.costGate={cpuCAatMostPoint97:result.C_over_A.checkerCpuMs.geometricMeanRatio<=limit.geometricCpu_C_over_A_atMost,cpuCBatMost1Point02:result.C_over_B.checkerCpuMs.geometricMeanRatio<=limit.geometricCpu_C_over_B_atMost,everyCpuCAfaster:triads.every((t:any)=>t.C.checkerCpuMs/t.A.checkerCpuMs<limit.everyCpuPair_C_over_A_below),wallCAatMost1:result.C_over_A.checkerWallMs.geometricMeanRatio<=limit.geometricWall_C_over_A_atMost,medianFootCAatMost1:result.C_over_A.medianFootprintRatio<=limit.medianFootprint_C_over_A_atMost,geometricFootCBatMostPoint95:result.C_over_B.footprintBytes.geometricMeanRatio<=limit.geometricFootprint_C_over_B_atMost};
result.costGatePassed=Object.values(result.costGate).every(Boolean);
console.log(JSON.stringify(result,null,2));

analyze-heap-owners.py.source:
import sys,json,hashlib,re,bisect,collections,array,os
from pathlib import Path
import ijson

def digest(path):
 h=hashlib.sha256()
 with open(path,'rb') as f:
  for block in iter(lambda:f.read(1048576),b''):h.update(block)
 return {'path':str(Path(path).resolve()),'sha256':h.hexdigest(),'bytes':os.path.getsize(path)}

def image_index(path):
 manifest=json.loads(Path(__file__).with_name('d0-ast-index-manifest.json').read_text())
 entry=manifest[str(Path(path).resolve())]
 assert digest(entry['path'])['sha256']==entry['sha256']
 index=json.loads(Path(entry['path']).read_text())
 assert index['image']['sha256']==digest(path)['sha256']
 return index['names'],index['aliases']

def sampled(report_paths,out):
 cache={};result={'schemaVersion':1,'diagnosticOnly':True,'scope':'Statistical sampled allocation bytes, not exact allocated/live/exclusive-retained bytes; uncollected includes garbage not yet collected. Source ownership uses the emitted function/continuation and may reflect compiler inlining.','roles':[]}
 for report_path in report_paths:
  report=json.loads(Path(report_path).read_text());image=report['image'];index,aliases=cache.setdefault(image,image_index(image)) if image not in cache else cache[image]
  row={'report':digest(report_path),'kind':report['kind'],'image':digest(image),'counts':report['stepCounts'],'boundaries':report['boundaries'],'samples':[],'indexedSourceAliases':len(aliases)}
  for s in report['samples']:
   profile=json.loads(Path(s['path']).read_text());sites={};groups=collections.Counter();nodes=[profile['head']];total=0;node_ids=set()
   while nodes:
    node=nodes.pop();nodes.extend(node.get('children',[]));size=node['selfSize'];total+=size
    assert node['id'] not in node_ids;node_ids.add(node['id'])
    if not size:continue
    frame=node['callFrame'];key=(frame['functionName'],frame['url'],frame['lineNumber'],frame['columnNumber']);sites[key]=sites.get(key,0)+size
    attribution=index.get(frame['functionName']) if Path(frame['url'].removeprefix('file://')).resolve()==Path(image).resolve() else None
    group=' | '.join(attribution['sourceOwners']) if attribution and attribution['sourceOwners'] else ('emitted-runtime:'+frame['functionName'] if attribution else 'other:'+frame['functionName'])
    groups[group]+=size
   sample_total=sum(x['size'] for x in profile.get('samples',[]));assert all(x['nodeId'] in node_ids for x in profile.get('samples',[]))
   top=[]
   for (name,url,line,col),size in sorted(sites.items(),key=lambda x:-x[1])[:35]:
    attribution=index.get(name) if Path(url.removeprefix('file://')).resolve()==Path(image).resolve() else None
    top.append({'functionName':name,'url':url,'lineNumber':line,'columnNumber':col,'estimatedBytes':size,'estimatedShare':size/total if total else 0,'sourceOwner':attribution})
   row['samples'].append({'label':s['label'],'step':s['step'],'profile':digest(s['path']),'statisticalNodeSelfBytes':total,'statisticalIndividualSampleBytes':sample_total,'nodeMinusSampleBytes':total-sample_total,'accounting':'Ownership weights use node.selfSize, matching prior analyzer; individual sample.size totals are retained separately. V8 returns slightly different estimates, not assumed equal.','sampleCount':len(profile.get('samples',[])),'memory':s['memory'],'spaces':s['spaces'],'topSourceOwners':[{'owner':k,'estimatedBytes':v,'share':v/total if total else 0} for k,v in groups.most_common(35)],'topSites':top})
  result['roles'].append(row)
 Path(out).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'output':out,'roles':[{'kind':r['kind'],'imageSha':r['image']['sha256'],'samples':[{'label':s['label'],'nodeSelfBytes':s['statisticalNodeSelfBytes'],'top':s['topSourceOwners'][:10]} for s in r['samples']]} for r in result['roles']]}))

def graph(path,out):
 with open(path,'rb') as f:meta=next(ijson.items(f,'snapshot'))
 nf=meta['meta']['node_fields'];ef=meta['meta']['edge_fields'];nw=len(nf);ew=len(ef)
 nt=meta['meta']['node_types'][0];et=meta['meta']['edge_types'][0]
 nodes=array.array('Q');edges=array.array('Q');strings=[]
 with open(path,'rb') as f:
  for prefix,event,value in ijson.parse(f):
   if prefix=='nodes.item' and event=='number':nodes.append(value)
   elif prefix=='edges.item' and event=='number':edges.append(value)
   elif prefix=='strings.item' and event=='string':strings.append(value)
 n=meta['node_count'];assert len(nodes)==n*nw and len(edges)==meta['edge_count']*ew
 idx={k:nf.index(k) for k in nf};eidx={k:ef.index(k) for k in ef}
 types=nodes[idx['type']::nw];sizes=nodes[idx['self_size']::nw];names=nodes[idx['name']::nw];counts=nodes[idx['edge_count']::nw]
 offsets=array.array('Q',[0]);running=0
 for c in counts:running+=c*ew;offsets.append(running)
 assert running==len(edges)
 tag_index=array.array('q',[-1])*n;shallow=collections.Counter();tagged=collections.Counter();tag_counts=collections.Counter();large=[]
 property_type=et.index('property');internal_type=et.index('internal');element_type=et.index('element')
 dollar=strings.index('$') if '$' in strings else -1
 for node in range(n):
  typ=nt[types[node]];name=strings[names[node]];shallow[(typ,name)]+=sizes[node]
  if sizes[node]>=1048576:large.append({'nodeIndex':node,'type':typ,'name':name[:300],'selfBytes':sizes[node]})
  if typ=='object':
   for off in range(offsets[node],offsets[node+1],ew):
    if edges[off+eidx['type']]==property_type and edges[off+eidx['name_or_index']]==dollar:
     target=edges[off+eidx['to_node']]//nw
     if nt[types[target]]=='string':tag_index[node]=names[target];tagged[strings[names[target]]]+=sizes[node];tag_counts[strings[names[target]]]+=1
     break
 def field_name(off):
  t=edges[off+eidx['type']];v=edges[off+eidx['name_or_index']]
  return str(v) if t in [element_type,et.index('hidden')] else strings[v]
 def data_edge(node,off):
  t=edges[off+eidx['type']]
  if t==property_type:return field_name(off) not in ['__proto__','constructor']
  if t==element_type:return True
  if t==internal_type:
   name=field_name(off)
   return name in ['elements','properties'] or (nt[types[node]] in ['concatenated string','sliced string'] and name!='map')
  return False
 number_type=nt.index('number');number_refs=collections.Counter()
 for node in range(n):
  for off in range(offsets[node],offsets[node+1],ew):
   target=edges[off+eidx['to_node']]//nw
   if types[target]!=number_type:continue
   owner=strings[tag_index[node]] if tag_index[node]>=0 else '['+nt[types[node]]+'] '+strings[names[node]][:80]
   edge=et[edges[off+eidx['type']]]
   field='$element' if edge in ['element','hidden'] else field_name(off)
   number_refs[(owner,edge,field)]+=1
 # A source-data graph is a deliberately restricted subset of strong edges.
 # It excludes closure/context/prototype/map reachability and does not claim
 # exclusive retained bytes. Each union counts shared nodes once.
 groups={}
 for tag in ['Arena','CheckerRunState','CheckerStackMore','MNode','MLeaf']:
  roots=[i for i,t in enumerate(tag_index) if t>=0 and strings[t].split('.')[-1]==tag]
  seen=bytearray(n);queue=array.array('Q',roots);head=0;total=0;objects=0;bytype=collections.Counter()
  for root in roots:seen[root]=1
  while head<len(queue):
   node=queue[head];head+=1;total+=sizes[node];objects+=1;bytype[nt[types[node]]]+=sizes[node]
   for off in range(offsets[node],offsets[node+1],ew):
    if not data_edge(node,off):continue
    target=edges[off+eidx['to_node']]//nw
    if not seen[target]:seen[target]=1;queue.append(target)
  groups[tag]={'roots':len(roots),'reachableNodes':objects,'sourceDataGraphShallowBytes':total,'bytesByNodeType':dict(bytype)}
  del seen,queue
 result={'schemaVersion':1,'diagnosticOnly':True,'snapshot':digest(path),'embeddedMetadata':meta,'nodeCount':n,'edgeCount':meta['edge_count'],'nodeShallowBytes':sum(sizes),'topNodeTypes':[{'type':a,'name':b[:300],'selfBytes':v} for (a,b),v in shallow.most_common(40)],'topTaggedObjects':[{'tag':tag,'count':tag_counts[tag],'selfBytes':v} for tag,v in tagged.most_common(40)],'largeNodes':sorted(large,key=lambda r:-r['selfBytes'])[:35],'sourceDataGraphUnions':groups,'edgePolicy':'Property except __proto__/constructor; elements; internal elements/properties and rope/sliced string backing links except map. Not general V8 retention/dominators or exclusive ownership. Overlapping unions must not be summed.','scope':'Snapshot is GC-perturbed prefix evidence, not a clean peak-RAM measurement. Shallow counts are exact for snapshot nodes; source-data graph unions are strong-edge subsets, not exclusive retained bytes.'}
 result['numericReferenceCensus']={'numberNodes':sum(t==number_type for t in types),'numberShallowBytes':sum(sizes[i] for i,t in enumerate(types) if t==number_type),'topIncomingEdges':[{'owner':owner,'edgeType':edge,'field':field,'references':count} for (owner,edge,field),count in number_refs.most_common(30)],'scope':'Incoming-reference counts, not exclusive bytes or stored numeric values. Does not prove Smi overflow, a specific numeric encoding cause, or a future speedup.'}
 Path(out).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'output':out,'nodeCount':n,'nodeShallowBytes':result['nodeShallowBytes'],'topTaggedObjects':result['topTaggedObjects'][:12],'dataGraphUnions':groups}))

if __name__=='__main__':
 if sys.argv[1]=='samples':sampled(sys.argv[2:-1],sys.argv[-1])
 elif sys.argv[1]=='snapshot':graph(sys.argv[2],sys.argv[3])
 else:raise ValueError('samples REPORT... OUT or snapshot SNAPSHOT OUT')

