import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {parse} from '/Users/ilyagulya/.bun/install/cache/acorn@8.19.0@@@1/dist/acorn.mjs';
const [path,out]=process.argv.slice(2),source=readFileSync(path,'utf8');
const ast=parse(source,{ecmaVersion:'latest',sourceType:'module',locations:true});
const privateName=x=>typeof x==='string'&&/^\$b[0-9]+$/.test(x);
const aliases=new Map(),functions=[],edges=new Map();let owner;
function visit(root,action){const stack=[root];while(stack.length){const node=stack.pop();if(!node||typeof node!=='object')continue;if(Array.isArray(node)){for(const item of node)if(item&&typeof item==='object')stack.push(item);continue;}if(typeof node.type==='string')action(node);for(const [key,value] of Object.entries(node)){if(key==='loc'||key==='start'||key==='end')continue;if(value&&typeof value==='object')stack.push(value);}}}
for(const node of ast.body){
 if(node.type==='FunctionDeclaration'&&node.id){
  const name=node.id.name;
  if(privateName(name))owner=name;
  const own=privateName(name)?name:(/^\$k[0-9]+$/.test(name)?owner:null);
  const callees=new Set();visit(node.body,x=>{if(x.type==='Identifier'&&privateName(x.name))callees.add(x.name);});
  if(own){if(!edges.has(own))edges.set(own,new Set());for(const callee of callees)edges.get(own).add(callee);}
  functions.push({name,lineNumber:node.loc.start.line-1,columnNumber:node.id.end-node.loc.start.column-node.start,privateOwner:own});
 }
 if(node.type==='ExpressionStatement'&&node.expression.type==='AssignmentExpression'){
  const assignment=node.expression,left=assignment.left;
  if(left.type==='MemberExpression'&&left.object.type==='Identifier'&&left.object.name==='$D'&&left.computed&&left.property.type==='Literal'&&typeof left.property.value==='string'){
   const refs=new Set();visit(assignment.right,x=>{if(x.type==='Identifier'&&privateName(x.name))refs.add(x.name);});
   if(refs.size===1){const target=[...refs][0];if(!aliases.has(target))aliases.set(target,[]);aliases.get(target).push(left.property.value);}
  }
 }
}
const reverse=new Map();for(const [from,tos]of edges)for(const to of tos){if(!reverse.has(to))reverse.set(to,new Set());reverse.get(to).add(from);}
function roots(start){const result=new Set(),seen=new Set(),stack=[start];while(stack.length){const x=stack.pop();if(!x||seen.has(x))continue;seen.add(x);if(aliases.has(x)){for(const name of aliases.get(x))result.add(name);continue;}for(const parent of reverse.get(x)||[])stack.push(parent);}return [...result].sort();}
const names={};for(const f of functions){if(names[f.name])throw Error('Duplicate top-level function '+f.name);names[f.name]={function:f.name,privateOwner:f.privateOwner,sourceOwners:roots(f.privateOwner),lineNumber:f.lineNumber,columnNumber:f.columnNumber};}
writeFileSync(out,JSON.stringify({schemaVersion:1,method:'Acorn AST top-level declarations/registration RHS identifiers; continuation follows its emitted private body; unregistered lifted bodies trace static incoming private references to registered roots. Runtime strings are never parsed as declarations.',image:{path,sha256:createHash('sha256').update(source).digest('hex')},aliases:Object.fromEntries(aliases),names})+'\n',{flag:'wx'});
let mapGet;for(const [name,sourceNames]of aliases)if(sourceNames.includes('Map.get')){mapGet=names[name];break;}
console.log(JSON.stringify({out,functions:functions.length,aliases:aliases.size,mapGet,runtimeSplitDone:names['$split_done']}));
